<script setup>
import {ref as paginationRef} from 'vue'
const listPageSize=paginationRef(20)
import ListPagination from '../../shared/components/ListPagination.vue'
import HelpTip from '../../shared/components/HelpTip.vue'
import {useTableLayout} from '../../shared/composables/tableLayout.js'
const {pinTableActions}=useTableLayout()

import {computed,inject,ref,watch,onBeforeUnmount} from 'vue'
import DataSyncDiff from './DataSyncDiff.vue'
import ApplicationResourcesEditor from './ApplicationResourcesEditor.vue'
import {toast} from '../../shared/composables/toast.js'
const props=defineProps({show:Boolean,inline:Boolean,services:{type:Array,default:()=>[]},environments:{type:Array,default:()=>[]},item:Object,approvedComparison:Object})
const emit=defineEmits(['close','generated','preview','query-approval','state'])
const api=inject('api'),tasks=ref([]),loading=ref(false),keyword=ref(''),page=ref(1),form=ref(null),original=ref(''),draft=ref(null),draftOriginal=ref(''),editorOpen=ref(false),editorRef=ref(null),resources=ref([]),resourceLoading=ref(false),source=ref(''),target=ref(''),comparison=ref(null),selected=ref([]),edited=ref({}),saving=ref(false),error=ref(''),editorError=ref(''),showBindings=ref(false),lastGenerated=ref(null),approvalID=ref(0)
let session=0,loadSequence=0,resourceSequence=0
onBeforeUnmount(()=>{session++;loadSequence++;resourceSequence++})
const dirty=computed(()=>!!form.value&&JSON.stringify(form.value)!==original.value)
const draftDirty=computed(()=>editorOpen.value&&JSON.stringify(draft.value)!==draftOriginal.value)
const state=computed(()=>({dirty:draftDirty.value,busy:saving.value}));watch(state,v=>emit('state',v),{immediate:true})
const envOptions=computed(()=>props.environments.map(e=>({value:e.name,label:e.display_name||e.name})))
const apps=computed(()=>props.services.map(s=>({value:s.name,label:s.name})))
const resourceOptions=computed(()=>resources.value.filter(r=>r.kind==='mysql').map(r=>({value:r.alias,label:r.alias})))
const filtered=computed(()=>tasks.value.filter(t=>!keyword.value||[t.name,t.service,t.resource_alias].some(v=>String(v||'').toLowerCase().includes(keyword.value.toLowerCase()))))
watch(keyword,()=>page.value=1)
async function load(){const request=++loadSequence;loading.value=true;error.value='';try{const result=await api('api/data-sync/tasks');if(request===loadSequence){if(!Array.isArray(result))throw Error('任务列表响应无效');tasks.value=result}}catch(e){if(request===loadSequence)error.value=e.message}finally{if(request===loadSequence)loading.value=false}}
watch(()=>props.show,v=>{session++;if(v){form.value=null;comparison.value=null;lastGenerated.value=null;editorOpen.value=false;load()}},{immediate:true})
function invalidate(){comparison.value=null;selected.value=[];edited.value={};approvalID.value=0}
watch([source,target,()=>JSON.stringify(form.value)],invalidate)
watch(()=>props.approvedComparison,async data=>{if(!data)return;form.value=JSON.parse(JSON.stringify(data.result.task));original.value=JSON.stringify(form.value);source.value=data.result.source_environment;target.value=data.result.target_environment;await Promise.resolve();comparison.value=data.result;approvalID.value=data.ticket.id;selected.value=[];edited.value=Object.fromEntries(data.result.differences.map(d=>[d.key,JSON.parse(JSON.stringify(d.after))]))})
async function resourcesFor(){const request=++resourceSequence;resources.value=[];resourceLoading.value=true;const name=draft.value?.service;try{if(name){const result=await api('api/services/'+encodeURIComponent(name)+'/resources');if(request===resourceSequence)resources.value=result.requirements||[]}}catch(e){if(request===resourceSequence)editorError.value=e.message}finally{if(request===resourceSequence)resourceLoading.value=false}}
const differentSQL=ref(false);let targetDraft=''
function open(task){if(saving.value)return;draft.value=task?JSON.parse(JSON.stringify(task)):{name:'',service:'',resource_alias:'',source_sql:'',target_sql:'',keys:[],mode:'table'};draft.value.keys ||= [];differentSQL.value=!!task&&task.source_sql!==task.target_sql;targetDraft=task?.target_sql||'';draftOriginal.value=JSON.stringify(draft.value);editorError.value='';editorOpen.value=true;resourcesFor()}
async function cancelEditor(){if(saving.value)return;if(!draftDirty.value||await confirmAction('已保存的任务和数据库数据不会改变。','放弃未保存的任务配置？',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑'}))editorOpen.value=false}
function mode(value){draft.value.mode=value;if(value==='tree')draft.value.tree={id_field:'id',parent_field:'parent_id',label_field:'name',root_value:'0'};else delete draft.value.tree}
function toggleSQL(value){if(value)draft.value.target_sql=targetDraft||draft.value.source_sql;else{targetDraft=draft.value.target_sql;draft.value.target_sql=draft.value.source_sql}}
watch(()=>draft.value?.source_sql,value=>{if(draft.value&&!differentSQL.value)draft.value.target_sql=value})
const keys=computed({get:()=>draft.value?.keys?.join(',')||'',set:text=>draft.value.keys=text.split(',').map(k=>k.trim()).filter(Boolean)})
async function save(){if(saving.value||resourceLoading.value)return;if(await validateFields(editorRef.value,draft.value,{},_validationErrors))return;saving.value=true;editorError.value='';const current=session;try{const result=await api('api/data-sync/tasks'+(draft.value.id?'/'+draft.value.id:''),{method:draft.value.id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(draft.value)});if(current!==session)return;if(form.value?.id===result.id){form.value=result;original.value=JSON.stringify(result);invalidate()}editorOpen.value=false;await load();toast('任务已保存，可从列表选择对比数据','success')}catch(e){editorError.value=e.message}finally{saving.value=false}}
function openComparison(task){if(saving.value)return;form.value=JSON.parse(JSON.stringify(task));original.value=JSON.stringify(form.value);source.value='';target.value='';lastGenerated.value=null;error.value='';invalidate()}
async function back(){if(saving.value)return;if(selected.value.length&&!await confirmAction('本次尚未生成草稿的差异选择和编辑将被清空。','返回任务列表？',{confirmButtonText:'返回列表',cancelButtonText:'继续核对'}))return;form.value=null;invalidate();error.value=''}
function close(){if(saving.value)return;if(draftDirty.value)return cancelEditor();emit('close')}
async function compare(){if(dirty.value)return error.value='请先保存任务修改，再对比';if(!source.value||!target.value)return error.value='请选择本次来源和目标环境';if(source.value===target.value)return error.value='来源和目标环境不能相同';saving.value=true;error.value='';invalidate();const current=session;try{const scope={source_environment:source.value,target_environment:target.value};if(props.inline){const policies=await Promise.all([source.value,target.value].map(env=>api(`api/policy?environment=${encodeURIComponent(env)}`)));if(current!==session)return;if(policies.some(p=>p.query_approval)){emit('query-approval',{task_id:form.value.id,scope});return}}const data=await api(`api/data-sync/tasks/${form.value.id}/compare`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(scope)});if(current!==session)return;comparison.value=data;selected.value=[];edited.value=Object.fromEntries(data.differences.map(d=>[d.key,JSON.parse(JSON.stringify(d.after))]))}catch(e){error.value=e.message}finally{saving.value=false}}
async function freeze(){if(dirty.value)return error.value='任务已有修改，请保存并重新对比';if(!comparison.value||!selected.value.length)return error.value='请勾选要同步的差异';saving.value=true;error.value='';const current=session;try{const work=props.item?await api(`api/work-items/${props.item.id}/delivery-content`):null;const data=await api(`api/data-sync/tasks/${form.value.id}/freeze`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source_environment:comparison.value.source_environment,target_environment:comparison.value.target_environment,digest:comparison.value.digest,query_approval_id:approvalID.value,work_item_id:props.item?.id||0,work_digest:work?.digest,rows:selected.value.map(key=>({key,after:edited.value[key]}))})});if(current!==session)return;lastGenerated.value=data;emit('generated',data);toast('已生成同步 SQL 草稿，未执行；请到变更提交预检目标库','success');invalidate()}catch(e){error.value=e.message}finally{saving.value=false}}
defineExpose({hasDraft:()=>draftDirty.value})

import OptionPicker from '../../shared/components/OptionPicker.vue'

import {reactive as _validationReactive} from 'vue'
import {validateFields,setFieldErrors,scrollToValidationField} from '../../shared/formValidation.js'
const _validationErrors=_validationReactive({})

import {confirmAction} from '../../shared/shadcnFeedback.js'


import {Badge,Button,Checkbox,Dialog,DialogContent,DialogDescription,DialogFooter,DialogHeader,DialogTitle,Empty,EmptyContent,EmptyDescription,EmptyHeader,Field,FieldDescription,FieldError,FieldLabel,Input,Spinner,Table,TableBody,TableCell,TableHead,TableHeader,TableRow,Textarea} from '../../shared/shadcn-ui.js'

import {InputGroup,InputGroupInput,InputGroupAddon,InputGroupButton} from '../../shared/shadcn-ui.js'

import {XIcon} from '@lucide/vue'
</script>
<template><Dialog :open="inline||show&&!editorOpen&&!showBindings" @update:open="v=>{if(!v)close()}"><component :is="inline?'section':DialogContent" :class="inline?'min-w-0':'flex max-h-[92dvh] flex-col overflow-auto sm:max-w-[min(1200px,94vw)]'" :show-close-button="!saving" @escape-key-down="e=>{if(saving)e.preventDefault()}" @interact-outside="e=>{if(saving)e.preventDefault()}"><DialogHeader v-if="!inline"><DialogTitle>数据同步</DialogTitle><DialogDescription class="sr-only">管理可复用的数据同步任务</DialogDescription></DialogHeader><div class="sync-tasks"><header class="sync-heading"><div><h2 v-if="inline">数据同步<HelpTip text="保存可复用的数据任务；对比时选择来源和目标环境。"/></h2></div><div class="flex flex-wrap items-center gap-2"><Button v-if="form" @click="back" variant="outline" size="default" type="button" :disabled="(saving)">返回任务列表</Button><Button @click="open()" variant="default" size="default" type="button" :disabled="(saving)">新建任务</Button></div></header><div v-if="error" role="alert" class="error">{{error}} <Button @click="load" variant="ghost" size="default" type="button">重试</Button></div><template v-if="!form"><div class="task-filters"><InputGroup  class="min-w-0 "><InputGroupInput v-model="keyword" placeholder="搜索任务、应用或数据库资源" v-bind="{'aria-label':'搜索数据同步任务'}"/><InputGroupAddon align="inline-end"><InputGroupButton v-if="keyword" :disabled="false" size="icon-xs" aria-label="清空输入" @click="keyword='' "><XIcon/></InputGroupButton></InputGroupAddon></InputGroup><Button @click="load" variant="outline" size="default" type="button" :disabled="(loading)"><Spinner v-if="loading"/>刷新</Button></div><div class="console-table min-w-0 max-w-full"><div v-if="loading" class="flex items-center gap-2 py-2" role="status"><Spinner/>正在读取</div><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:1000}).y?({x:1000}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:1000}).x||({x:1000}).minWidth||1130)+'px'}"><TableHeader><TableRow><TableHead :style="{width:(220)+'px'}">任务名称</TableHead><TableHead :style="{width:(200)+'px'}">应用</TableHead><TableHead :style="{width:(200)+'px'}">数据库资源</TableHead><TableHead :style="{width:(140)+'px'}">数据结构</TableHead><TableHead :style="{width:(180)+'px'}">匹配键</TableHead><TableHead :class="(pinTableActions?'right':undefined)==='right'?'sticky right-0 z-10 bg-background':(pinTableActions?'right':undefined)==='left'?'sticky left-0 z-10 bg-background':''" :style="{width:(190)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (filtered||[]).slice((page-1)*(listPageSize),page*(listPageSize))" :key="typeof (&quot;id&quot;)==='function'?(&quot;id&quot;)(record):record[&quot;id&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}">{{record["name"]}}</div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}">{{record["service"]}}</div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}">{{record["resource_alias"]}}</div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record} in [{record,rowIndex}]"><Badge variant="secondary">{{record.mode==='tree'?'树状层级':'表格数据'}}</Badge></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record} in [{record,rowIndex}]">{{record.keys?.join('、')||'—'}}</template></div></TableCell><TableCell class="align-top" :class="(pinTableActions?'right':undefined)==='right'?'sticky right-0 z-10 bg-background':(pinTableActions?'right':undefined)==='left'?'sticky left-0 z-10 bg-background':''"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><div class="flex flex-wrap items-center gap-2"><Button @click="openComparison(record)" variant="ghost" size="sm" type="button" :disabled="(saving)">对比数据</Button><Button @click="open(record)" variant="ghost" size="sm" type="button" :disabled="(saving)">编辑</Button></div></template></div></TableCell></TableRow></template><TableRow v-if="!(filtered||[]).length"><TableCell :colspan="6"><Empty><EmptyHeader><EmptyDescription>{{keyword?'没有匹配的任务':'暂无数据同步任务'}}</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div><ListPagination :page="page" :total="(filtered||[]).length" :page-size="listPageSize" @update:page="page=$event" @update:page-size="listPageSize=$event;page=1" :disabled="loading"/></div></template><template v-else><dl class="task-summary grid min-w-0 gap-4"><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">任务</dt><dd class="min-w-0 break-words">{{form.name}}</dd></div><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">应用</dt><dd class="min-w-0 break-words">{{form.service}}</dd></div><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">数据库资源</dt><dd class="min-w-0 break-words">{{form.resource_alias}}</dd></div></dl><section class="comparison-scope"><h3>本次对比<HelpTip text="仅执行只读查询；生成同步草稿后仍需预检和审批，目标独有数据保留。"/></h3><div class="flex flex-wrap items-center gap-2"><Field ><FieldLabel as="div">来源环境</FieldLabel><OptionPicker v-model="source" :disabled="saving" placeholder="选择来源环境" class="min-w-36" :options="envOptions"/></Field><span>→</span><Field ><FieldLabel as="div">目标环境</FieldLabel><OptionPicker v-model="target" :disabled="saving" placeholder="选择目标环境" class="min-w-36" :options="envOptions"/></Field><Button @click="compare" variant="default" size="default" type="button" :disabled="(saving)"><Spinner v-if="saving"/>对比数据（只读）</Button></div></section><template v-if="comparison"><p>{{comparison.source_environment}} → {{comparison.target_environment}} · 差异 {{comparison.differences.length}} 行 · 一致 {{comparison.unchanged}} 行 · 目标独有 {{comparison.target_only}} 行（保留）</p><DataSyncDiff :comparison="comparison" v-model:selected="selected" :edited="edited" :saving="saving"/><Button @click="freeze" variant="default" size="default" type="button" :disabled="(!selected.length)||(saving)"><Spinner v-if="saving"/>生成同步草稿{{item?'并关联当前需求':''}}（{{selected.length}} 行）</Button></template></template><section v-if="lastGenerated" class="result"><b>已生成同步草稿 #{{lastGenerated.id}}</b><p>未执行数据库写入。</p><pre>{{lastGenerated.sql.content}}</pre><Button @click="emit('preview',lastGenerated)" variant="outline" size="default" type="button">继续预检目标库（只读）</Button></section></div></component></Dialog><Dialog :open="editorOpen&amp;&amp;!showBindings" @update:open="async v=>{if(!v){cancelEditor()}}"><DialogContent class="flex max-h-[92dvh] flex-col gap-0 overflow-hidden p-0 sm:max-w-[var(--editor-width)]" :class="false?'inset-0 h-dvh max-h-dvh w-screen max-w-none translate-x-0 translate-y-0 rounded-none sm:max-w-none':''" :style="{'--editor-width':typeof (&quot;min(840px,94vw)&quot;)==='number'?(&quot;min(840px,94vw)&quot;)+'px':(&quot;min(840px,94vw)&quot;)}" :show-close-button="!saving" @interact-outside="e=>{if(!(false))e.preventDefault()}" @escape-key-down="e=>{if(!(!saving))e.preventDefault()}"><DialogHeader class="shrink-0 border-b p-5 pr-12"><DialogTitle>{{draft?.id?'编辑数据同步任务':'新建数据同步任务'}}</DialogTitle><DialogDescription class="sr-only">详情与操作</DialogDescription></DialogHeader><div class="min-h-0 flex-1 overflow-auto p-5"><form ref="editorRef" @submit.prevent=""><fieldset v-if="draft"   class="task-config min-w-0 space-y-5" :disabled="saving"><div class="config-grid"><Field data-validation-field="name" :data-validation-rules="JSON.stringify([{required:true,message:'请填写任务名称'}])" :data-invalid="!!_validationErrors['name']" @vue:mounted="delete _validationErrors['name']"><FieldLabel>任务名称</FieldLabel><Input v-model="draft.name" placeholder="例如：系统菜单迁移"/><FieldError v-if="_validationErrors['name']">{{_validationErrors['name'].message}}</FieldError></Field><Field data-validation-field="service" :data-validation-rules="JSON.stringify([{required:true,message:'请选择应用'}])" :data-invalid="!!_validationErrors['service']" @vue:mounted="delete _validationErrors['service']"><FieldLabel>应用</FieldLabel><OptionPicker v-model="draft.service" placeholder="选择应用" @change="draft.resource_alias='';resourcesFor()" class="min-w-36" :options="apps"/><FieldError v-if="_validationErrors['service']">{{_validationErrors['service'].message}}</FieldError></Field></div><Field data-validation-field="resource_alias" :data-validation-rules="JSON.stringify([{required:true,message:'请选择数据库资源'}])" :data-invalid="!!_validationErrors['resource_alias']" @vue:mounted="delete _validationErrors['resource_alias']"><FieldLabel>逻辑数据库资源</FieldLabel><OptionPicker v-model="draft.resource_alias" placeholder="选择已绑定的数据库资源" class="min-w-36" :options="resourceOptions"/><FieldDescription>按所选环境解析实际数据库。<Button @click="showBindings=true" variant="ghost" size="xs" type="button" :disabled="(!draft.service)">配置应用资源</Button></FieldDescription><FieldError v-if="_validationErrors['resource_alias']">{{_validationErrors['resource_alias'].message}}</FieldError></Field><Field data-validation-field="mode" :data-invalid="!!_validationErrors['mode']" @vue:mounted="delete _validationErrors['mode']"><FieldLabel>数据结构</FieldLabel><OptionPicker :model-value="draft.mode||'table'" @change="mode" class="min-w-36" :options="[{value:'table',label:'表格数据'},{value:'tree',label:'树状层级（菜单）'}]"/><FieldError v-if="_validationErrors['mode']">{{_validationErrors['mode'].message}}</FieldError></Field><Field data-validation-field="source_sql" :data-validation-rules="JSON.stringify([{required:true,message:'请填写只读查询 SQL'}])" :data-invalid="!!_validationErrors['source_sql']" @vue:mounted="delete _validationErrors['source_sql']"><FieldLabel>{{differentSQL?'来源查询 SQL':'对比查询 SQL'}}</FieldLabel><Textarea v-model="draft.source_sql" placeholder="SELECT id, code, name FROM menu WHERE ..." :rows="({minRows:4,maxRows:10}).minRows||4"/><FieldError v-if="_validationErrors['source_sql']">{{_validationErrors['source_sql'].message}}</FieldError></Field><Field><FieldLabel class="flex items-center gap-2 font-normal"><Checkbox v-model="differentSQL" @update:model-value="toggleSQL($event)"/>目标使用不同查询 SQL</FieldLabel></Field><Field v-if="differentSQL" data-validation-field="target_sql" :data-validation-rules="JSON.stringify([{required:true,message:'请填写目标查询 SQL'}])" :data-invalid="!!_validationErrors['target_sql']" @vue:mounted="delete _validationErrors['target_sql']"><FieldLabel>目标查询 SQL</FieldLabel><Textarea v-model="draft.target_sql" :rows="({minRows:4,maxRows:10}).minRows||4"/><FieldError v-if="_validationErrors['target_sql']">{{_validationErrors['target_sql'].message}}</FieldError></Field><Field data-validation-field="keys" :data-validation-rules="JSON.stringify([{type:'array',required:true,message:'请填写匹配键'}])" :data-invalid="!!_validationErrors['keys']" @vue:mounted="delete _validationErrors['keys']"><FieldLabel>{{draft.mode==='tree'?'稳定匹配键（菜单编码、权限标识）':'匹配键'}}</FieldLabel><Input v-model="keys" placeholder="多个字段以逗号分隔"/><FieldDescription>{{draft.mode==='tree'?'查询包含完整祖先链；ID 与父 ID 自动映射。':'匹配键须对应目标主键或唯一索引。'}}单表显式字段 SELECT + WHERE，最多 1000 行，两侧查询字段须一致。</FieldDescription><FieldError v-if="_validationErrors['keys']">{{_validationErrors['keys'].message}}</FieldError></Field><div v-if="draft.mode==='tree'&&draft.tree" class="config-grid"><Field data-validation-field="tree.id_field" :data-validation-rules="JSON.stringify([{required:true,message:'请填写 ID 字段'}])" :data-invalid="!!_validationErrors['tree.id_field']" @vue:mounted="delete _validationErrors['tree.id_field']"><FieldLabel>ID 字段</FieldLabel><Input v-model="draft.tree.id_field"/><FieldError v-if="_validationErrors['tree.id_field']">{{_validationErrors['tree.id_field'].message}}</FieldError></Field><Field data-validation-field="tree.parent_field" :data-validation-rules="JSON.stringify([{required:true,message:'请填写父 ID 字段'}])" :data-invalid="!!_validationErrors['tree.parent_field']" @vue:mounted="delete _validationErrors['tree.parent_field']"><FieldLabel>父 ID 字段</FieldLabel><Input v-model="draft.tree.parent_field"/><FieldError v-if="_validationErrors['tree.parent_field']">{{_validationErrors['tree.parent_field'].message}}</FieldError></Field><Field data-validation-field="tree.label_field" :data-validation-rules="JSON.stringify([{required:true,message:'请填写名称字段'}])" :data-invalid="!!_validationErrors['tree.label_field']" @vue:mounted="delete _validationErrors['tree.label_field']"><FieldLabel>菜单名称字段</FieldLabel><Input v-model="draft.tree.label_field"/><FieldError v-if="_validationErrors['tree.label_field']">{{_validationErrors['tree.label_field'].message}}</FieldError></Field><Field data-validation-field="tree.root_value" :data-invalid="!!_validationErrors['tree.root_value']" @vue:mounted="delete _validationErrors['tree.root_value']"><FieldLabel>根节点父 ID</FieldLabel><Input v-model="draft.tree.root_value"/><FieldError v-if="_validationErrors['tree.root_value']">{{_validationErrors['tree.root_value'].message}}</FieldError></Field></div><p v-if="editorError" role="alert" class="error">{{editorError}}</p></fieldset></form></div><DialogFooter class="shrink-0 flex-wrap border-t p-4"><Button @click="cancelEditor" variant="outline" size="default" type="button" :disabled="(saving)">取消</Button><Button @click="save" variant="default" size="default" type="button" :disabled="(resourceLoading)||(saving)"><Spinner v-if="saving"/>保存任务</Button></DialogFooter></DialogContent></Dialog><ApplicationResourcesEditor :show="showBindings" :services="services" :initial-service="draft?.service||''" @close="showBindings=false;resourcesFor()"/></template>
<style scoped>.sync-tasks{display:grid;gap:16px;min-width:0}.sync-heading{display:flex;align-items:center;justify-content:space-between;gap:16px}.hint{color:var(--muted-foreground);font-size:.875rem;margin-top:6px}.task-filters{display:flex;gap:12px}.comparison-scope{border:1px solid var(--border);padding:16px;border-radius:var(--radius)}.comparison-scope label{display:grid;gap:6px;min-width:180px}.config-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 20px}.error{color:var(--error)}.result{padding:16px;border:1px solid var(--border)}pre{white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:650px){.config-grid{grid-template-columns:1fr}.sync-heading{align-items:flex-start;flex-direction:column}}</style>

